CREATE TABLE `measure_qa_runs` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`property_id` integer NOT NULL,`status` text NOT NULL,`error_count` integer NOT NULL,`warning_count` integer NOT NULL,`review_count` integer NOT NULL,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE INDEX `measure_qa_runs_property_idx` ON `measure_qa_runs` (`property_id`);
CREATE TABLE `measure_qa_findings` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`qa_run_id` integer NOT NULL,`window_id` integer,`measurement_version_id` integer,`code` text NOT NULL,`severity` text NOT NULL,`message_en` text NOT NULL,`message_zh` text NOT NULL,`field_link` text DEFAULT '' NOT NULL,`status` text DEFAULT 'open' NOT NULL,`override_reason` text,`overridden_by` integer,`overridden_at` text,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL); CREATE INDEX `measure_qa_findings_run_idx` ON `measure_qa_findings` (`qa_run_id`);
